package com.certpath.api;
import com.certpath.api.ApiModels.*;import com.certpath.service.CertService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/certifications") @RequiredArgsConstructor public class CertificationController{private final CertService service;@GetMapping ApiResponse<Page<CertificationCardDto>> list(@RequestParam(required=false)String query,@RequestParam(required=false)String job,@RequestParam(required=false)String category,@RequestParam(required=false)String type,@RequestParam(required=false)String difficulty,@RequestParam(defaultValue="recommended")String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){return ApiResponse.ok(service.search(query,job,category,type,difficulty,sort,page,Math.min(size,50)));}@GetMapping("/{id}")ApiResponse<CertificationDetailDto> detail(@PathVariable Long id){return ApiResponse.ok(service.detail(id));}}
